//! 📚️ Original source frames publish bounded coordinates only after exact committed-span verification.
use semio_framework_value_native_owned::native_decoding::NativeDecodeCloseControl;
use protocol::{codec::{RetainedWireByteSource,OriginalWireSourceIdentity,HistoryReadLimits},format::retained::{RetainedSprVerification,RetainedSprLimits}};
use semio_framework_value::{ValueError, ValueRefusalKind, RetainedCloneGrant, RetainedCloneProgress, RetirementDemand};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
#[derive(Debug,PartialEq,Eq)]
pub struct RetainedHistorySourceFrame{start:usize,end:usize,payload:(usize,usize),kind:u8,flags:u8,raw_bytes:Option<u64>}
impl RetainedHistorySourceFrame{
 pub fn original_range(&self)->(usize,usize){(self.start,self.end)}
 pub fn payload_range(&self)->(usize,usize){self.payload}
 pub fn kind(&self)->u8{self.kind}
 pub fn flags(&self)->u8{self.flags}
 pub fn raw_bytes(&self)->Option<u64>{self.raw_bytes}
}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedHistorySourceFramesStep{Blocked,Progress,Frame,Ready,Closed}
pub struct RetainedHistorySourceFrames{source:OriginalWireSourceIdentity,control_identity:(u64,Option<u64>),range:(usize,usize),limits:HistoryReadLimits,verifier:Option<RetainedSprVerification>,position:usize,sequence:u64,records:usize,pending:Option<RetainedHistorySourceFrame>,verified:bool,closing:bool,closed:bool,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>}
fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn permits(g:RetainedCloneGrant,d:RetirementDemand)->bool{g.maximum_items>0&&g.maximum_depth>=d.depth&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes}
fn scalar<S:RetainedWireByteSource+?Sized>(source:&S,position:&mut usize,end:usize)->Result<u64,ValueError>{let mut value=0;for index in 0..10{let byte=source.byte_at(*position).filter(|_|*position<end).ok_or_else(||fault("original verified frame scalar is absent"))?;if index==9&&byte>1{return Err(fault("original verified frame scalar overflows"))}*position+=1;value|=u64::from(byte&127)<<(index*7);if byte&128==0{return Ok(value)}}Err(fault("original verified frame scalar is unbounded"))}
impl RetainedHistorySourceFrames{
 pub fn admit<S:RetainedWireByteSource+?Sized>(source:&S,range:(usize,usize),limits:HistoryReadLimits,control:&NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<Option<Self>,ValueError>{limits.validate()?;let identity=source.original_source_identity();if range.0>range.1||range.1>identity.extent||identity.extent>limits.file_bytes as usize{return Err(fault("original History frame source exceeds declared policy"))}if g.maximum_items==0||g.maximum_depth==0{return Ok(None)}let verifier=RetainedSprVerification::new((range.1-range.0)as u64,RetainedSprLimits{file_bytes:u64::from(limits.file_bytes),frame_body_bytes:u64::from(limits.frame_body_bytes),records:u64::from(limits.records)}).map_err(|_|fault("original History frame verification admission failed"))?;Ok(Some(Self{source:identity,control_identity:(control.ledger_identity(),control.retirement_recipient_identity()),range,limits,verifier:Some(verifier),position:range.0,sequence:0,records:0,pending:None,verified:false,closing:false,closed:false,receipt:Some((g,RetainedCloneProgress{copied_items:1,..Default::default()}))}))}
 fn validate<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&dyn NativeDecodeCloseControl)->Result<(),ValueError>{if self.source!=source.original_source_identity()||self.control_identity!=(control.ledger_identity(),control.retirement_recipient_identity()){return Err(fault("original History frames changed source or receiving owner"))}Ok(())}
 fn publish(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.receipt=Some((g,p));if !p.fits(g){return Err(fault("original History frame receipt exceeded caller grant").with_retained_progress(p))}Ok(())}
 pub fn receipt(&self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt}
 pub fn take_receipt(&mut self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt.take()}
 pub fn source_identity(&self)->OriginalWireSourceIdentity{self.source}
 pub fn original_range(&self)->(usize,usize){self.range}
 pub fn consumed_end(&self)->usize{self.position}
 pub fn committed_sequence(&self)->u64{self.sequence}
 pub fn is_ready(&self)->bool{self.verified&&self.position==self.range.1&&self.pending.is_none()&&self.receipt.is_none()&&!self.closing&&!self.closed}
 pub fn frame_is_receivable(&self)->bool{self.pending.is_some()&&self.receipt.is_none()&&!self.closing&&!self.closed}
 pub fn demands<S:RetainedWireByteSource+?Sized>(&self,source:&S,control:&dyn NativeDecodeCloseControl,body:usize)->Result<RetirementDemand,ValueError>{self.validate(source,control)?;if self.closed||self.receipt.is_some(){return Ok(Default::default())}Ok(RetirementDemand{copy_bytes:if self.closing||self.verified{0}else{body.min(self.range.1-self.position).max(usize::from(self.position<self.range.1))},depth:1,..Default::default()})}
 pub fn step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistorySourceFramesStep,ValueError>{self.validate(source,control)?;if self.closed||self.closing||self.receipt.is_some(){return Ok(RetainedHistorySourceFramesStep::Blocked)}if self.is_ready(){return Ok(RetainedHistorySourceFramesStep::Ready)}if self.pending.is_some(){return Ok(RetainedHistorySourceFramesStep::Frame)}let d=self.demands(source,control,g.maximum_copy_bytes)?;if !permits(g,d){return Ok(RetainedHistorySourceFramesStep::Blocked)}control.checkpoint()?;
  if !self.verified{let initial=self.verifier.as_ref().unwrap().consumed();let result=(||{let verifier=self.verifier.as_mut().unwrap();for position in self.position..self.position+d.copy_bytes{let byte=source.byte_at(position).ok_or_else(||fault("original History verification source byte is absent"))?;let mut fuel=1;verifier.push(&[byte],&mut fuel).map_err(|_|fault("original History frame or commit verification failed"))?;self.position=position+1;}if self.position==self.range.1{let span=verifier.finish().map_err(|_|fault("original History frame verification is incomplete"))?;if span.sequence()==0||span.end()!=(self.range.1-self.range.0)as u64||span.tail()!=0{return Err(fault("original History requires one exact committed span"))}self.sequence=span.sequence();self.verifier=None;self.verified=true;self.position=self.range.0+32;}Ok(())})();let copied_bytes=self.verifier.as_ref().map_or(d.copy_bytes,|verifier|(verifier.consumed()-initial)as usize);let progress=RetainedCloneProgress{copied_items:1,copied_bytes,..Default::default()};self.publish(g,progress)?;if let Err(error)=result{self.cancel();return Err(error.with_retained_progress(progress))}return Ok(RetainedHistorySourceFramesStep::Progress)}
  let start=self.position;let mut position=start;let length=usize::try_from(scalar(source,&mut position,self.range.1)?).map_err(|_|fault("original verified frame extent exceeds platform"))?;if length<2||length>self.limits.frame_body_bytes as usize{return Err(fault("original verified frame body exceeds declared policy"))}let payload_end=position.checked_add(length).ok_or_else(||fault("original verified frame body overflows"))?;let end=payload_end.checked_add(8).filter(|end|*end<=self.range.1).ok_or_else(||fault("original verified frame escaped committed source"))?;let kind=source.byte_at(position).ok_or_else(||fault("original verified frame kind is absent"))?;let flags=source.byte_at(position+1).ok_or_else(||fault("original verified frame flags are absent"))?;position+=2;let raw_bytes=if flags&1!=0{Some(scalar(source,&mut position,payload_end)?)}else{None};if position>payload_end{return Err(fault("original verified frame payload range is invalid"))}if self.records>=self.limits.records as usize{return Err(fault("original verified frame count exceeds declared policy"))}self.pending=Some(RetainedHistorySourceFrame{start,end,payload:(position,payload_end),kind,flags,raw_bytes});self.records+=1;self.publish(g,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistorySourceFramesStep::Frame)
 }
 pub fn take_frame_into<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,control:&NativeDecodeControl<'_>,recipient:&mut Option<RetainedHistorySourceFrame>,g:RetainedCloneGrant)->Result<bool,ValueError>{self.validate(source,control)?;if !self.frame_is_receivable()||recipient.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}let original=self.pending.take().unwrap();self.position=original.end;*recipient=Some(original);self.publish(g,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(true)}
 pub fn cancel(&mut self){self.closing=true;if let Some(verifier)=self.verifier.as_mut(){verifier.cancel()}}
 pub fn close_step<S:RetainedWireByteSource+?Sized>(&mut self,source:&S,control:&dyn NativeDecodeCloseControl,g:RetainedCloneGrant)->Result<RetainedHistorySourceFramesStep,ValueError>{self.validate(source,control)?;if self.closed{return Ok(RetainedHistorySourceFramesStep::Closed)}if !self.closing||self.receipt.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(RetainedHistorySourceFramesStep::Blocked)}self.verifier=None;self.pending=None;self.closed=true;self.publish(g,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistorySourceFramesStep::Closed)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.verifier.is_none()&&self.pending.is_none()&&self.receipt.is_none()}
}
impl Drop for RetainedHistorySourceFrames{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original History frames abandoned receiving metadata")}}
